    ["mumble mumble..."] = "mırıldanma mırıldanma...",
    ["%s falls to the ground. His spirit is released with his last breath."] = "%s yere düşer. ",
    ["Step away from the Lieutenant's belongings!"] = "Teğmenin eşyalarından uzak durun!",
    ["%s listens to YOUR_NAME's report..."] = "%s, YOUR_NAME'in raporunu dinliyor...",
    ["What?? The Burning Blade is Spreading! We must investigate!"] = "Ne?? Yanan Bıçak Yayılıyor! ",
    ["I thank you YOUR_NAME. And my brother thanks you."] = "Size teşekkür ederim YOUR_NAME. Ve kardeşim size teşekkür ediyor.",
    ["Orgnil Soulscar smashes the dead, twisted claw."] = "Orgnil Soulscar ölüleri parçalıyor, çarpık pençe.",
    ["We will suffer no demon's servant in our lands!"] = "Topraklarımızda hiçbir iblisin hizmetkarına izin vermeyeceğiz!",
    ["%s enters a trance..."] = "%s transa giriyor...",
    ["%s is burned by unleashed magic!"] = "%s serbest bırakılmış sihirle yanıyor...",
    ["YOUR_NAME, unlocking the secret of these collars is beyond my skills..."] = "YOUR_NAME, bu tasmaların sırrını çözmek yeteneklerimin ötesinde...",
    ["Argh!"] = "Ah!",
    ["%s inspects the Searing Collar..."] = "%s Yakıcı Tasmayı inceliyor...",
    ["Interesting, very interesting. You found this in Durotar, YOUR_NAME?"] = "İlginç, çok ilginç. ",
    ["The collar is indeed infused with demonic power, YOUR_NAME. This bodes ill for our people."] = "Bu tasma gerçekten de şeytani güçle dolu, YOUR_NAME. Bu, halkımız için kötüye işaret.",
    ["Hm...it is good that you brought this to me, YOUR_NAME."] = "Hm...bunu bana getirdiğiniz iyi oldu, YOUR_NAME.",
    ["A dangerous device this is, YOUR_NAME. I am glad you brought it to my attention."] = "Bu tehlikeli bir cihaz, YOUR_NAME. ",
    ["Fresh Bread! Get your oven fresh bread here!"] = "Taze Ekmek! Fırından yeni çıkmış ekmeğinizi buradan alın!",
    ["Get'em while they are nice and fresh! Loaves of bread here!"] = "Taze ve tazeyken alın! Ekmek somunları burada!",
